#!/usr/bin/env python3
"""Development-only real FFmpeg progress, owned cancellation and concurrency."""
from __future__ import annotations
import argparse
import ctypes
import datetime as dt
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import platform
import re
import shutil
import subprocess
import sys
import threading
import time

INSTRUMENTATION = r'''
# Development-only scalar observations and explicitly selected pacing/signals.
function Write-WacHarnessEvent {
    param([System.Collections.IDictionary]$Record)
    if (-not $env:WAC_HARNESS_EVENTS) { return }
    if (-not (Get-Variable WacHarnessSequence -Scope Global -ErrorAction SilentlyContinue)) { $global:WacHarnessSequence=0 }
    $global:WacHarnessSequence++
    $Record.sequence=$global:WacHarnessSequence
    $Record.atUtc=[DateTime]::UtcNow.ToString('o')
    $Record.hostPid=$PID
    $Record.inputPath=$script:inputPath
    [IO.File]::AppendAllText($env:WAC_HARNESS_EVENTS, ($Record | ConvertTo-Json -Depth 8 -Compress)+"`n", [Text.UTF8Encoding]::new($false))
}
$script:WacHarnessNative=${function:Invoke-WacNativeProcess}
$script:WacHarnessUpdate=${function:Update-WacProgress}
$script:WacHarnessDisplay=${function:Write-WacProgress}
$script:WacHarnessPublish=${function:Publish-WacOutputTransaction}
function Write-WacProgress {
    param($State,[switch]$Completed)
    & $script:WacHarnessDisplay @PSBoundParameters
    $stateRecord=[ordered]@{}
    foreach ($property in $State.PSObject.Properties) {
        if ($property.Name -notin @('RunContext','Snapshot')) { $stateRecord[$property.Name]=$property.Value }
    }
    Write-WacHarnessEvent -Record ([ordered]@{kind='progress';state=$stateRecord;snapshot=$State.Snapshot;displayCompleted=[bool]$Completed})
}
function Update-WacProgress {
    param($State,$Snapshot)
    & $script:WacHarnessUpdate @PSBoundParameters
    if ($env:WAC_HARNESS_ACTION -and $env:WAC_HARNESS_TARGET_INPUT -and
        [string]$script:inputPath -ieq $env:WAC_HARNESS_TARGET_INPUT -and
        [string]$State.Stage -ceq $env:WAC_HARNESS_STAGE -and
        $null -ne $Snapshot -and $Snapshot.OutTimeMicroseconds -gt 0 -and $State.ProcessId -and
        -not (Test-Path -LiteralPath $env:WAC_HARNESS_ACTION_MARKER)) {
        $owned=[Diagnostics.Process]::GetProcessById([int]$State.ProcessId)
        try {
            if ($owned.HasExited) { return }
            $record=[ordered]@{kind=$env:WAC_HARNESS_ACTION;ownedPid=$owned.Id;ownedStartUtc=$owned.StartTime.ToUniversalTime().ToString('o')
                ownedAliveBefore=$true;stage=$State.Stage;processedSeconds=$State.ProcessedSeconds
                cancellationBefore=$State.RunContext.IsCancellationRequested;fileIndex=$State.FileIndex;fileCount=$State.FileCount}
            if ($env:WAC_HARNESS_ACTION -eq 'request') { Request-WacCancellation -RunContext $State.RunContext }
            elseif ($env:WAC_HARNESS_ACTION -eq 'unexpected_owned_exit') { $owned.Kill() }
            else { throw 'Unknown development action.' }
            $record.cancellationAfter=$State.RunContext.IsCancellationRequested
            [IO.File]::WriteAllText($env:WAC_HARNESS_ACTION_MARKER, ($record | ConvertTo-Json -Compress), [Text.UTF8Encoding]::new($false))
            Write-WacHarnessEvent -Record $record
        } finally { $owned.Dispose() }
    }
}
function Invoke-WacNativeProcess {
    param([string]$FilePath,[AllowEmptyCollection()][string[]]$ArgumentList=@(),
        [int]$TimeoutMilliseconds=0,[int]$StreamCloseTimeoutMilliseconds=5000,
        [System.IO.Stream]$StandardInputStream,$RunContext,$ProgressState)
    $originalArguments=@($ArgumentList)
    $paced=$false
    $target=($env:WAC_HARNESS_PACE_ALL -eq '1') -or
        ($env:WAC_HARNESS_TARGET_INPUT -and [string]$script:inputPath -ieq $env:WAC_HARNESS_TARGET_INPUT -and
         (-not $env:WAC_HARNESS_STAGE -or [string]$ProgressState.Stage -ceq $env:WAC_HARNESS_STAGE))
    if ($target -and $null -ne $ProgressState -and $env:WAC_HARNESS_READRATE) {
        $inputIndex=[array]::IndexOf($ArgumentList,'-i')
        if ($inputIndex -lt 0) { throw 'Selected pacing stage has no native input.' }
        $before=@();if ($inputIndex -gt 0) { $before=@($ArgumentList[0..($inputIndex-1)]) }
        $ArgumentList=$before+@('-readrate',$env:WAC_HARNESS_READRATE)+@($ArgumentList[$inputIndex..($ArgumentList.Count-1)])
        if ($env:WAC_HARNESS_INITIAL_BURST) { $ArgumentList=@('-readrate_initial_burst',$env:WAC_HARNESS_INITIAL_BURST)+$ArgumentList }
        $PSBoundParameters.ArgumentList=$ArgumentList
        $paced=$true
    }
    Write-WacHarnessEvent -Record ([ordered]@{kind='native_start';executable=$FilePath;arguments=@($ArgumentList);originalArguments=$originalArguments
        paced=$paced;stage=$(if ($ProgressState) {$ProgressState.Stage} else {$null});inputStream=($null -ne $StandardInputStream)
        timeoutMilliseconds=$TimeoutMilliseconds;culture=[Threading.Thread]::CurrentThread.CurrentCulture.Name;shellVersion=$PSVersionTable.PSVersion.ToString()})
    $result=& $script:WacHarnessNative @PSBoundParameters
    $resultRecord=[ordered]@{kind='native_result';stage=$(if ($ProgressState) {$ProgressState.Stage} else {$null})
        started=$result.Started;exitCode=$result.ExitCode;cancelled=$result.Cancelled;ownedProcessId=$result.OwnedProcessId
        timedOut=$result.TimedOut;error=$result.Error;cleanupError=$result.CleanupError;progress=$result.Progress
        cancellationInputError=$result.CancellationInputError
        stdoutHasProgress=($result.StandardOutput -match '(?m)^out_time_us=|^progress=');stderrHasProgress=($result.StandardError -match '(?m)^out_time_us=|^progress=')}
    Write-WacHarnessEvent -Record $resultRecord
    $result
}
function Publish-WacOutputTransaction {
    param($Transaction)
    & $script:WacHarnessPublish @PSBoundParameters
    Write-WacHarnessEvent -Record ([ordered]@{kind='published';path=$Transaction.FinalPath;published=[bool]$Transaction.Published})
}
'''


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--ffmpeg',type=Path,required=True)
    parser.add_argument('--ffprobe',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    parser.add_argument('--shell',action='append',choices=['ps51','ps7'])
    parser.add_argument('--case',action='append',choices=['fast','accurate','preview-fast','preview-accurate','unknown-fast','variable-speed','cancel-analysis','cancel-rendering','cancel-verification','unexpected-exit'])
    args=parser.parse_args()
    repo=Path(__file__).resolve().parents[2]
    output=args.output.resolve()
    if not output.is_relative_to(repo/'.wac-local/WAC-M3-04'): parser.error('Output outside ignored M3-04 scratch')
    output.mkdir(parents=True,exist_ok=False)
    for name in ['app','fixtures','cases','logs','references']: (output/name).mkdir()
    ffmpeg,ffprobe=args.ffmpeg.resolve(strict=True),args.ffprobe.resolve(strict=True)
    helper=repo/'scripts/Test-MeasuredLoudness.py'
    spec=importlib.util.spec_from_file_location('progress_media_helpers',helper); helpers=importlib.util.module_from_spec(spec)
    previous=sys.dont_write_bytecode
    try:
        sys.dont_write_bytecode=True;spec.loader.exec_module(helpers)
    finally: sys.dont_write_bytecode=previous
    sha=helpers.sha256
    names=['WinAudioClean.ps1','WinAudioClean.IO.ps1','WinAudioClean.Preview.ps1','WinAudioClean.Settings.ps1','WinAudioClean.Batch.ps1','WinAudioClean.Queue.ps1']
    sources=[repo/name for name in names]+[helper,Path(__file__).resolve(),repo/'docs/codex/winaudioclean/BASELINE.json']
    immutable={}
    jobs=[]
    reference_cache={}
    clean_env={key:value for key,value in os.environ.items() if key.upper()!='PSMODULEPATH' and not key.upper().startswith('WAC_HARNESS_')}
    evidence={'task':'WAC-M3-04','started_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'scope':{'shell_filter':args.shell,'case_filter':args.case,'unfiltered':not args.shell and not args.case},
              'notice':'Actual new run-context cancellation against active owned FFmpeg; copied stage pacing and programmatic signal are labeled. Separate genuine console-control evidence is owned by parent. No listening/keyboard/Explorer claim.',
              'source_revision':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),
              'source_sha256_before':{p.relative_to(repo).as_posix():sha(p) for p in sources},'harness_invocation':sys.orig_argv,
              'environment':{'python':platform.python_version(),'platform':platform.platform(),'child_psmodulepath_removed':True},
              'tools':{name:{'path':str(path),'sha256':sha(path)} for name,path in [('ffmpeg',ffmpeg),('ffprobe',ffprobe)]},'commands':[],'fixtures':[],'cases':[],'references':[]}

    def require(value,message):
        if not value: raise ValueError(message)

    def sanitize(value):
        if isinstance(value,str):
            for original,replacement in [(str(repo),'<repo>'),(str(Path.home()),'<user-profile>')]:
                pattern=r'[\\/]+'.join(re.escape(part) for part in re.split(r'[\\/]+',original))
                value=re.sub(pattern,lambda match:replacement,value,flags=re.I)
            value=re.sub(r'(<S N="(?:User|Computer|PSComputerName)">)[^<]*(</S>)',r'\1&lt;local-identity&gt;\2',value)
            for key in ['USERNAME','COMPUTERNAME','USERDOMAIN']:
                if os.environ.get(key):value=re.sub(re.escape(os.environ[key]),'<local-identity>',value,flags=re.I)
            return value
        if isinstance(value,dict):return {key:sanitize(item) for key,item in value.items()}
        if isinstance(value,list):return [sanitize(item) for item in value]
        return value

    def remember(path):
        path=Path(path);digest=sha(path);immutable[path]=digest
        return {'path':path.relative_to(repo).as_posix(),'sha256':digest,'bytes':path.stat().st_size}

    def start(label,command,env=None):
        child=subprocess.Popen([str(v) for v in command],cwd=repo,env=env or clean_env,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        job={'id':label,'command':[str(v) for v in command],'pid':child.pid,'process':child,'started':time.monotonic(),'buffers':{},'threads':[]}
        jobs.append(job)
        for name,stream in [('stdout',child.stdout),('stderr',child.stderr)]:
            def drain(name=name,stream=stream):job['buffers'][name]=stream.read()
            thread=threading.Thread(target=drain,daemon=True);thread.start();job['threads'].append(thread)
        return job

    def finish(job,timeout=150,binary=False):
        child=job['process'];timed_out=False
        try:child.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out=True;helpers.stop_owned_process_tree(child);child.wait(timeout=10)
        for thread in job['threads']:thread.join(timeout=10)
        require(all(not thread.is_alive() for thread in job['threads']),'Harness redirected reader failed to close')
        record={key:job[key] for key in ['id','command','pid']};record.update(exit_code=child.returncode,timed_out=timed_out,elapsed_seconds=round(time.monotonic()-job['started'],3))
        returned={}
        for name,data in job['buffers'].items():
            raw=binary and name=='stdout';path=output/'logs'/(job['id']+'-'+name+('.pcm' if raw else '.txt'))
            if raw:path.write_bytes(data)
            else:path.write_text(sanitize(data.decode('utf-8',errors='replace')),encoding='utf-8')
            record[name+'_native_bytes_sha256']=hashlib.sha256(data).hexdigest();record[name+'_log']=path.relative_to(repo).as_posix();record[name+'_sanitized_log_sha256']=sha(path)
            returned[name]=data if raw else data.decode('utf-8',errors='replace')
        evidence['commands'].append(record)
        job['recorded']=True
        return dict(record,**returned)

    def checked(label,command,binary=False):
        result=finish(start(label,command),binary=binary)
        require(result['exit_code']==0 and not result['timed_out'],label+' failed')
        return result

    def quote(value):return "'"+str(value).replace("'","''")+"'"

    def audio(label,path,bits,channels,frames):
        metadata=json.loads(checked('probe-'+label,[ffprobe,'-v','error','-show_streams','-of','json',path])['stdout'])['streams'];require(len(metadata)==1,'Published output has extra streams')
        stream=metadata[0];pcm=checked('decode-'+label,[ffmpeg,'-nostdin','-hide_banner','-v','error','-i',path,'-map','0:a:0','-c:a',f'pcm_s{bits}le','-f',f's{bits}le','-'],True)['stdout']
        expected_layout={1:'mono',2:'stereo'}[channels]
        checks={'codec':stream['codec_name']==f'pcm_s{bits}le','bits':int(stream['bits_per_sample'])==bits,'rate':int(stream['sample_rate'])==48000,
                'channels':stream['channels']==channels,'layout':(stream.get('channel_layout') or expected_layout)==expected_layout,'frames':len(pcm)==frames*channels*(bits//8)}
        require(all(checks.values()),label+' audio format/frame check failed')
        return dict(remember(path),frames=len(pcm)//channels//(bits//8),decoded_pcm_sha256=hashlib.sha256(pcm).hexdigest(),checks=checks)

    def read_events(path,live=False):
        if not path.exists():return []
        text=path.read_text(encoding='utf-8-sig')
        if live and text and not text.endswith('\n'):text=text.rsplit('\n',1)[0] if '\n' in text else ''
        return [json.loads(line) for line in text.splitlines() if line]

    def app_job(case_id,shell,culture,inputs,destination,loudness='Fast',preview=False,extra_env=None,application=None,bits=16,mono=False):
        folder=output/'cases'/case_id;folder.mkdir(exist_ok=True);destination.mkdir(exist_ok=True)
        events=folder/'events.jsonl';marker=folder/'action.json';journal=folder/'batch.jsonl'
        options=' -Mode Raw -Preset '+('Gentle' if bits==24 else 'Original')+' -LoudnessMode '+loudness+' -BitDepth '+str(bits)+' -Mono:$'+str(mono).lower()
        if len(inputs)>1:options+=' -InputPaths @('+','.join(quote(p) for p in inputs)+') -BatchResultPath '+quote(journal)
        else:options+=' -inputPath '+quote(inputs[0])
        if preview:options+=' -Preview -PreviewStartSeconds 1 -PreviewDurationSeconds 4'
        command="$culture=[Globalization.CultureInfo]::GetCultureInfo("+quote(culture)+");[Threading.Thread]::CurrentThread.CurrentCulture=$culture;[Threading.Thread]::CurrentThread.CurrentUICulture=$culture;& "+quote(application or output/'app/WinAudioClean.ps1')+options+' -OutputDirectory '+quote(destination)+' -FfmpegPath '+quote(ffmpeg)+' -FfprobePath '+quote(ffprobe)+' -SettingsPath '+quote(folder/'absent-settings.json')+' -IgnoreSavedSettings -NonInteractive;exit $LASTEXITCODE'
        env=dict(clean_env,WAC_HARNESS_EVENTS=str(events),WAC_HARNESS_ACTION_MARKER=str(marker));env.update(extra_env or {})
        job=start('app-'+case_id,[shell,'-NoLogo','-NoProfile','-ExecutionPolicy','Bypass','-Command',command],env)
        return {'job':job,'events':events,'marker':marker,'journal':journal,'destination':destination,'id':case_id}

    def inspect_finished(case,expected_exit=(0,7),bits=16,mono=False,frames=384000):
        result=finish(case['job']);require(result['exit_code'] in expected_exit and not result['timed_out'],case['id']+' unexpected application exit')
        events=read_events(case['events']);remember(case['events'])
        reports=[];assets=[]
        for path in sorted(case['destination'].glob('WinAudioClean_*.json')):
            record=remember(path);report=json.loads(path.read_text(encoding='utf-8-sig'))
            if report.get('reportType')=='preview':
                for role,item in report['assets'].items():assets.append(dict(audio(case['id']+'-'+role,Path(item['path']),bits,1 if mono else 2,frames),role=role))
            elif report.get('processingStatus')=='SUCCESS':
                expected_frames=frames[Path(report['input']['path']).name] if isinstance(frames,dict) else frames
                assets.append(audio(case['id']+'-'+str(report['jobId']),Path(report['output']['path']),bits,1 if mono else 2,expected_frames))
            reports.append(dict(record,report=report))
        return {'result':{k:v for k,v in result.items() if k not in ['stdout','stderr']},'events':events,'reports':reports,'assets':assets}

    def progress_checks(events,success,published_count):
        displays=[event for event in events if event['kind']=='progress'];pubs=[event for event in events if event['kind']=='published']
        values=[event['state']['Percent'] for event in displays]
        checks={'progress_observed':bool(displays),'bounded_percent':all(-1<=value<=100 for value in values),
                'stage_labels_nonempty':all(event['state']['Stage'] for event in displays),
                'stderr_not_progress':all(not event['stderrHasProgress'] for event in events if event['kind']=='native_result'),
                'no_100_before_publication':all(len([p for p in pubs if p['sequence']<event['sequence'] and p['inputPath']==event['inputPath'] and p['published']])>=published_count for event in displays if event['state']['Percent']==100),
                'successful_terminal_100':not success or any(value==100 for value in values)}
        native=[event for event in events if event['kind']=='native_start' and event['stage']]
        checks['structured_progress_arguments']=bool(native) and all('-progress' in event['arguments'] and event['arguments'][event['arguments'].index('-progress')+1]=='pipe:1' and '-nostats' in event['arguments'] and '-stats' not in event['arguments'] for event in native)
        checks['stage_ranges']=all(event['state']['Percent']==-1 or event['state']['Stage']=='Completed' or event['state']['StartPercent']<=event['state']['Percent']<=event['state']['EndPercent'] for event in displays)
        groups={}
        for event in displays:
            state=event['state'];key=(event['inputPath'],state['FileIndex'],state['Stage'],state['StartPercent'],state['EndPercent'])
            groups.setdefault(key,[]).append(state['Percent'])
        checks['stage_percent_monotonic']=all(values==sorted(values) for values in groups.values())
        checks['nonzero_native_snapshot']=any(event['state']['ProcessedSeconds']>0 and event['state'].get('ProcessId') for event in displays)
        return checks

    def reported_graphs_match(data):
        checks=[]
        for record in data['reports']:
            report=record['report']
            natives=[e for e in data['events'] if e['kind']=='native_start' and e['inputPath']==report['input']['path'] and e['stage'] and '-af' in e['arguments']]
            filters={event['stage']:event['arguments'][event['arguments'].index('-af')+1] for event in natives}
            if report.get('reportType')=='preview':
                for stage,role in [('Preview Original rendering','Original'),('Preview Processed rendering','Processed'),('Preview Original comparison','CompareOriginal'),('Preview Processed comparison','CompareProcessed')]:
                    checks.append(filters.get(stage)==report['assets'][role]['exactFilters'])
            else:
                checks.append(filters.get('Rendering')==report['settings']['exactFilters'])
                if report['settings']['loudnessMode']=='Accurate':
                    checks.append(filters.get('Analysis')==report['normalization']['analysisFilter'])
                    checks.append(filters.get('Verification')==report['normalization']['finalMeasurementFilter'])
        return bool(checks) and all(checks)

    def alive(pid):
        kernel=ctypes.WinDLL('kernel32',use_last_error=True)
        kernel.OpenProcess.argtypes=[ctypes.c_uint32,ctypes.c_int,ctypes.c_uint32];kernel.OpenProcess.restype=ctypes.c_void_p
        kernel.GetExitCodeProcess.argtypes=[ctypes.c_void_p,ctypes.POINTER(ctypes.c_uint32)];kernel.GetExitCodeProcess.restype=ctypes.c_int
        kernel.CloseHandle.argtypes=[ctypes.c_void_p]
        handle=kernel.OpenProcess(0x1000,False,int(pid))
        if not handle:return False
        try:
            code=ctypes.c_uint32();return bool(kernel.GetExitCodeProcess(handle,ctypes.byref(code))) and code.value==259
        finally:kernel.CloseHandle(handle)

    def accurate_original_reference(host,shell,culture,source_input,frame_count):
        key=(host,frame_count)
        if key not in reference_cache:
            case_id=host+'-accurate-original-'+str(frame_count)+'-reference'
            reference=app_job(case_id,shell,culture,[source_input],output/'references'/case_id,'Accurate',application=repo/'WinAudioClean.ps1')
            result=finish(reference['job']);require(result['exit_code'] in (0,7) and not result['timed_out'],case_id+' ordinary reference failed')
            paths=list(reference['destination'].glob('WinAudioClean_*.json'));require(len(paths)==1,'Expected one ordinary reference report')
            record=remember(paths[0]);report=json.loads(paths[0].read_text(encoding='utf-8-sig'));require(report['processingStatus']=='SUCCESS','Ordinary reference did not publish')
            asset=audio(case_id,Path(report['output']['path']),16,2,frame_count)
            data={'id':case_id,'application_exit':result['exit_code'],'assets':[asset],'reports':[dict(record,report=report)]}
            evidence['references'].append(data);reference_cache[key]=data
        return reference_cache[key]

    try:
        source=(repo/'WinAudioClean.ps1').read_text(encoding='utf-8-sig');marker='# Explicit local support export bypasses media/dependency initialization.'
        require(source.count(marker)==1,'Early instrumentation marker missing/ambiguous')
        require('function Update-WacProgress' in source,'Runtime progress API not ready')
        (output/'app/WinAudioClean.ps1').write_text(source.replace(marker,INSTRUMENTATION+marker),encoding='utf-8-sig')
        for name in names[1:]:shutil.copyfile(repo/name,output/'app'/name)
        copies_before={p.name:sha(p) for p in (output/'app').iterdir()}
        evidence['instrumentation']={'seam':'Copied main before support/settings routes; native/update/display/publication wrappers delegate real implementations. Selected input readrate pacing and real Request or owned PID unexpected-exit actions explicitly recorded. No simulated130.',
                                     'source':INSTRUMENTATION,'copies_before':copies_before}
        for name,path in [('ffmpeg',ffmpeg),('ffprobe',ffprobe)]:evidence['tools'][name]['version']=checked(name+'-version',[path,'-version'])['stdout'].splitlines()[0]
        fixture=output/'fixtures/stereo.wav';short=output/'fixtures/short.wav'
        for path,seconds in [(fixture,8),(short,1)]:evidence['fixtures'].append(dict(helpers.create_fixture(path,2,seconds,'eligible'),**remember(path)))
        unknown=output/'fixtures/live.webm'
        checked('create-live-webm',[ffmpeg,'-nostdin','-hide_banner','-v','error','-i',fixture,'-c:a','libopus','-f','webm','-live','1',unknown])
        evidence['fixtures'].append(dict(remember(unknown),description='Actual live WebM container without duration metadata.'))
        probe=json.loads(checked('probe-live-source',[ffprobe,'-v','error','-show_streams','-show_format','-of','json',unknown])['stdout'])
        require(all('duration' not in s and 'DURATION' not in s.get('tags',{}) for s in probe['streams']),'Live fixture unexpectedly supplies stream duration')
        evidence['unknown_source_metadata']=probe
        shells={'ps51':str(Path(os.environ['SystemRoot'])/'System32/WindowsPowerShell/v1.0/powershell.exe'),'ps7':shutil.which('pwsh')}
        success_cases=['fast','accurate','preview-fast','preview-accurate','unknown-fast','variable-speed']
        for host in args.shell or ['ps51','ps7']:
            shell=shells[host];require(shell,host+' unavailable');culture={'ps51':'en-US','ps7':'de-DE'}[host]
            for name in success_cases:
                if args.case and name not in args.case:continue
                case_id=host+'-'+name;dest=output/'cases'/case_id/'exports';source_input=unknown if name=='unknown-fast' else fixture
                accurate='accurate' in name;preview=name.startswith('preview');bits=24 if accurate else 16;mono=accurate
                if name=='unknown-fast':
                    case=app_job(case_id,shell,culture,[unknown],dest)
                    rejected=finish(case['job']);require(rejected['exit_code']==4 and not rejected['timed_out'],'Unknown input did not retain fail-closed timing policy')
                    rejection_events=read_events(case['events']);remember(case['events'])
                    native_events=output/'cases'/case_id/'unknown-native-events.jsonl';native_result=output/'cases'/case_id/'unknown-native-result.json'
